import importlib

mods = [
    "pypdf", "PyPDF2", "pdfplumber", "reportlab", "pypdfium2",
    "fitz", "PIL", "pdf2image", "pytesseract", "numpy", "pandas",
]
for m in mods:
    try:
        mod = importlib.import_module(m)
        print(f"{m}: OK  ({getattr(mod, '__version__', '?')})")
    except Exception as e:
        print(f"{m}: MISSING ({type(e).__name__})")

import re

def parse_pdf(data):
    m = re.search(rb"startxref\s+(\d+)", data)
    xref_offset = int(m.group(1))
    lines = data[xref_offset:data.find(b"trailer", xref_offset)].splitlines()
    entries = {}
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if line in (b"xref", b""):
            i += 1
            continue
        mm = re.fullmatch(rb"(\d+)\s+(\d+)", line)
        if mm:
            start, count = int(mm.group(1)), int(mm.group(2))
            for k in range(count):
                e = lines[i + 1 + k].split()
                entries[start + k] = int(e[0]) if e[2] == b"n" else None
            i += 1 + count
        else:
            i += 1
    bodies = {}
    for num, off in entries.items():
        if off is None:
            continue
        start = data.find(b"obj", off)
        body_start = start + 3
        if data[body_start:body_start + 1] == b"\r":
            body_start += 1
        if data[body_start:body_start + 1] == b"\n":
            body_start += 1
        end = data.find(b"endobj", body_start)
        bodies[num] = data[body_start:end]
    return entries, bodies

def get_ref(body, key):
    m = re.search(rb"/%s\s+(\d+)\s+0\s+R" % key, body)
    return int(m.group(1)) if m else None

def get_kids(body):
    m = re.search(rb"/Kids\s*\[(.*?)\]", body, re.DOTALL)
    if not m:
        return []
    return [int(x) for x in re.findall(rb"(\d+)\s+0\s+R", m.group(1))]

for path in ["report_with_cover.pdf", "report.pdf"]:
    print("=" * 30, path)
    with open(path, "rb") as f:
        data = f.read()
    entries, bodies = parse_pdf(data)
    print("entries:", {k: v for k, v in sorted(entries.items())})
    for num in sorted(bodies):
        body = bodies[num]
        preview = body if len(body) < 200 else body[:180] + b"..."
        print(f"--- obj {num} ---")
        print(preview.decode("latin-1", errors="replace"))
    cats = [n for n, b in bodies.items() if b"/Type /Catalog" in b]
    print("catalog objs:", cats)
    if cats:
        for c in cats:
            po = get_ref(bodies[c], b"Pages")
            print(f"catalog {c} -> Pages {po}: {bodies.get(po, b'<missing>')[:120]!r}")
            if po in bodies:
                print("   kids:", get_kids(bodies[po]))

